def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrap(func):
        lru_cache = LRU(maxsize)

        def is_expired(key):
            try:
                expire_time = lru_cache[key][1]
                return expire_time <= timer()
            except KeyError:
                return True

        def get(key):
            try:
                value, expire_time = lru_cache[key]
                lru_cache.move_to_end(key)
                return value
            except KeyError:
                raise KeyError("Key not found in the cache")

        def set(key, value):
            expire_time = timer() + ttl
            lru_cache[key] = (value, expire_time)

        def delete(key):
            if is_expired(key):
                raise KeyError("Key not found in the cache")
            del lru_cache[key]

        def cache():
            return lru_cache

        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs))
                try:
                    value = get(key)
                except KeyError:
                    value = func(*args, **kwargs)
                    set(key, value)
                return value
            return wrapper

        def clear():
            lru_cache.clear()

        decorator.get = get
        decorator.set = set
        decorator.delete = delete
        decorator.cache = cache
        decorator.clear = clear
        return decorator
    return wrap

