def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Negation):
            # Negative absorption
            if arg.negation in args:
                new_args.append(LogicalAnd(arg.operand, arg.negation))
            else:
                new_args.append(arg)
        elif isinstance(arg, Disjunction):
            # Absorption
            if arg.left in args:
                new_args.append(arg.left)
            elif arg.right in args:
                new_args.append(arg.right)
            else:
                new_args.append(arg)
        else:
            # no absorption or negative absorption
            new_args.append(arg)
    return new_args

